/* ------------------------- /config/payments ------------------------- */
// Card processor shown on checkout, and the card networks it accepts (drives the badges and card validation).
// Payment brand marks, cropped from the brand sheet supplied by BatteryHub (light = on white, dark = on navy).
// American Express was not in that sheet, so it still shows as a text badge until its mark is added here.
const PAYMENT_LOGOS = Object.freeze({
  mastercard_light: 'data:image/webp;base64,',
  mastercard_dark: 'data:image/webp;base64,',
  visa_light: 'data:image/webp;base64,',
  visa_dark: 'data:image/webp;base64,',
  apple_pay_light: 'data:image/webp;base64,',
  apple_pay_dark: 'data:image/webp;base64,',
  google_pay_light: 'data:image/webp;base64,',
  google_pay_dark: 'data:image/webp;base64,',
});
// Acceptance badges under the pay buttons. logoSrc: an official, licensed mark (SVG file path or data URI)
// from each brand's merchant resources; when set it replaces the text badge everywhere.
const PAYMENT_BADGES = Object.freeze({
  visa:       { label: 'Visa',       logoSrc: PAYMENT_LOGOS.visa_light },
  mastercard: { label: 'Mastercard', logoSrc: PAYMENT_LOGOS.mastercard_light },
  amex:       { label: 'AMEX',       logoSrc: null },
  jcb:        { label: 'JCB',        logoSrc: null },
  unionpay:   { label: 'UnionPay',   logoSrc: null },
  apple_pay:  { label: 'Apple Pay',  logoSrc: PAYMENT_LOGOS.apple_pay_light },
  google_pay: { label: 'Google Pay', logoSrc: PAYMENT_LOGOS.google_pay_light },
});
const PAYMENT_PROCESSOR = Object.freeze({ name: 'Stripe', networks: ['visa', 'mastercard', 'amex'] });
const PAYMENT_METHODS = Object.freeze({
  // logoSrc: drop the official, licensed Apple Pay / Google Pay mark (SVG or data URI) here and it replaces the
  // animated wallet glyph on the express buttons. Production can instead render the wallets' own SDK buttons.
  apple_pay:  { id: 'apple_pay',  label: 'pay.apple',     express: true,  platform: 'apple',   icon: 'phone', glyph: 'tap',    logoSrc: null },
  google_pay: { id: 'google_pay', label: 'pay.google',    express: true,  platform: 'android', icon: 'phone', glyph: 'wallet', logoSrc: null },
  card:       { id: 'card',       label: 'pay.card',      express: false, icon: 'card', form: true },
});
